s": [{"rel": "auto_has_risk", "node": "RISK:LEAKAGE_LOOKAHEAD"}, {"rel": "auto_has_risk", "node": "RISK:OUTCOME_DERIVED_LABEL"}]}, {"id": "FAM:SF19", "label": "Study family SF19: Portability confirmatory T1 (signature travels beyond profile-matched decoys)", "score": 0.21, "reached_via": ["FAM:SF-PAP-016 auto_related_family (repeat_order_unknown) FAM:SF19", "FAM:SF-PAP-016 auto_related_family (repeat_order_unknown) FAM:SF19"], "attributes": {"observed_research_question": "Portability confirmatory T1 (signature travels beyond profile-matched decoys)", "auto_outcome_status": "supported", "observed_hypothesis": "A mover's displacement signature is more similar across franchises than profile-matched destination decoys' signatures.", "observed_result": ["[APPS-084] median self_sim=+0.129 decoy_sim=+0.049; T1 median Delta=+0.0557 perm_p=0.0050; 173/294=0.5884 sign_test_p=2.872e-03; dest-fr CI [+0.0192,+0.0859]. All three decision-rule bars True. T1 CONFIRMED.", "[PAP-017] Final: median Delta=+0.0557, perm p=0.0050, dest-fr CI[+0.0192,+0.0859]; 173/294=58.8% positive, sign p=2.87e-3. Prereg record: 296 movers, Delta=+0.0819, CI[+0.037,+0.125]"], "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "[APPS-084] Delta>0, perm<0.01, CI excludes 0 at destination-franchise clustering."}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:PLACEBO_DEPENDENCE"}]}], "n_results": 4}

