   {"code": "OUTCOME_DERIVED_LABEL", "text": "Role labels come from the same play-by-play as outcomes, so classification can encode the outcome."}
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": ["FAM:SF29", "FAM:SF-PAP-009", "FAM:SF-PAP-032", "FAM:SF19"],
  "summary": "Earlier work covers role coverage (SF29, SF-PAP-009; powered null), travel/fit screening (SF-PAP-032; inconclusive) and portability of displacement signatures (SF19; supported). None tests cut-heavy versus drive-heavy shapers, so the specific question is not answered, though portability has been studied in an adjacent form."
 },
 "risks": [
  {"code": "SAMPLE_SIZE_POWER", "text": "n=24 units gives low power; a null would be uninformative and a significant result would likely be inflated."},
  {"code": "EXPOSURE_SPARSITY", "text": "Few units may contain enough cut-heavy or drive-heavy possessions to estimate role-specific effects."},
  {"code": "MEASURE_RELIABILITY", "text": "Play-type classification from derived play-by-play records may be noisy and unstable across seasons."},
  {"code": "OUTCOME_DERIVED_LABEL", "text": "Role labels and outcome measures both come from play-by-play; the classification must be fixed before outcomes are examined."},
  {"code": "LEAKAGE_LOOKAHEAD", "text": "Using partial 2025-26 regular-season or playoff data, or using full-season role labels to predict within-season outcomes, would leak future information."},
  {"code": "CONFOUNDING", "text": "Talent, team context and minutes distribution can confound a cut-heavy versus drive-heavy comparison."},
  {"code": "DRIFT_NONSTATIONARITY", "text": "Play style and rule or tracking changes across 2022-23 to 2025-26 can shift role definitions over time."},
  {"code": "PLACEBO_DEPENDENCE", "text": "SF19 was recorded with a placebo-style decoy design; portability results may depend on how decoys are matched."},
  {"code": "MULTIPLE_TESTING", "text": "Several role definitions, thresholds and outcomes give many comparisons; without correction, a spurious portability difference is likely."},
  {"code": "LABEL_ERROR", "text": "Misattributed play types or shooter identities in the play-by-play would misclassify shapers."}
 ],
 "predicted_outcome": {
  "supported": 0.08,
  "rejected": 0.22,
  "untestable": 0.2,
  "artifact": 0.1,
  "uncertain": 0.4
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "Difference in portability (out-of-context performance or signature similarity retention) between cut-heavy and drive-heavy shapers, as a contrast of predefined role-share classes.",
  "unit": "Shaper-season (player-level mover records), not the 24-unit count, if the unit count cannot be raised; each unit defined before analysis.",
  "sample": "Not feasible at n=24 as posed. Minimum viable: all shapers with defined role shares across 2022-23 to 2024-25 complete seasons (regular season and playoffs), with 2025-26 only after completion (regular season from 2026-04-13, playoffs from 2026-06-21).",
  "power": "Pre-register an MDE before analysis; if the MDE exceeds the plausible effect range or the number of units is below the level of the SF29 run (72 units), do not run the confirmatory test.",
  "controls": "Talent proxy, team context, minutes share and usage, with role classes fixed on pre-period data; outcomes measured in a later window than the role labels.",
  "falsification": "Placebo role labels (shuffled within player) and a decoy-matched comparison as in SF19; a null on placebo labels is required before a positive result counts.",
  "multiplicity": "One primary contrast (cut-heavy minus drive-heavy portability), with any secondary definitions reported as exploratory and corrected.",
  "decision_rule": "Positive only if the primary contrast's CI excludes zero at the pre-registered threshold, survives the placebo test, and the sample meets the pre-registered MDE; otherwise report as uninformative or null.",
  "data_version": "NBA 2022-23 through 2024-25 regular season and playoffs (complete); 2025-26 regular season only after 2026-04-13 and playoffs only after 2026-06-21; freeze all role definitions before 2025-26 data are used."
 }
}

